import{_ as n,o as r,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Hochdruckreiniger","description":"","frontmatter":{},"headers":[],"relativePath":"de/car-wash/pressure-washers.md","filePath":"de/car-wash/pressure-washers.md"}'),a={name:"de/car-wash/pressure-washers.md"};function d(s,e,o,u,c,l){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="hochdruckreiniger" tabindex="-1">Hochdruckreiniger <a class="header-anchor" href="#hochdruckreiniger" aria-label="Permalink to &quot;Hochdruckreiniger&quot;">​</a></h1><p>Hochdruckreiniger sind die Variante zur Selbstbedienung: Der Spieler parkt, geht zu einem Hochdruckreiniger und reinigt das Fahrzeug Stufe für Stufe. Jede entfernte Schmutzstufe wird bezahlt.</p><h2 id="wo-sie-stehen" tabindex="-1">Wo sie stehen <a class="header-anchor" href="#wo-sie-stehen" aria-label="Permalink to &quot;Wo sie stehen&quot;">​</a></h2><p>Es gibt zwei Möglichkeiten, und du kannst beide nutzen:</p><ul><li><strong>Welt-Props</strong>: Jeder in <code>ManualModels</code> aufgeführte Prop wird zum Hochdruckreiniger, überall wo die Karte einen hat. Standardmäßig ist das <code>prop_gas_airunit01</code>, die Luftstation an Tankstellen.</li><li><strong>Stationen, die du platzierst</strong>: Füge in <code>/nay</code> einen Eintrag zu <code>ManualStations</code> hinzu, stell dich an die gewünschte Stelle und drücke <strong>Meine Position verwenden</strong>.</li></ul><p>Ist <code>ShowBlips</code> an, erscheinen die platzierten Stationen auf der Karte.</p><h2 id="wie-spieler-sie-nutzen" tabindex="-1">Wie Spieler sie nutzen <a class="header-anchor" href="#wie-spieler-sie-nutzen" aria-label="Permalink to &quot;Wie Spieler sie nutzen&quot;">​</a></h2><ul><li>Ist <code>InteractionMode</code> auf <code>key</code> gesetzt, gehen Spieler zum Hochdruckreiniger und drücken <strong>E</strong>.</li><li>Mit <code>target</code> nutzen sie das Target-Auge (ox_target oder qb-target).</li></ul><p>Die Schmutzstufe des Fahrzeugs und der Preis pro Stufe werden angezeigt. Die Reinigung entfernt alle <code>ManualSecondsPerLevel</code> Sekunden eine Stufe, und jede Stufe kostet <code>ManualPricePerLevel</code>, abgebucht von dem in <code>Account</code> eingestellten Konto. Spieler können jederzeit aufhören und zahlen nur für das, was sie gereinigt haben.</p><p>Mit <code>ManualEnabled</code> schaltest du alle Hochdruckreiniger ab. Alle Einstellungen findest du auf der Seite <a href="/de/car-wash/settings#hochdruckreiniger">Einstellungen</a>.</p>',10)])])}const p=n(a,[["render",d]]);export{g as __pageData,p as default};
